export function briefFor(board){return caseBriefs[board.id]||{title:board.title,question:'¿Puedes explicar esta placa por bloques?',level:'Exploración',minutes:15,focus:board.blocks?.[0]?.id,concept:'La forma de un componente ayuda a reconocer su familia; sus conexiones permiten estudiar su función dentro de la placa.',observe:'Encuentra entrada, salida y referencia. Anota qué componentes puedes identificar con certeza.',evidence:'Selecciona un bloque, sigue sus redes y justifica una conexión relevante.',limit:board.fidelity||'La vista reproduce los datos del modelo; no equivale a una medida sobre un equipo físico.'};}
export function createCase(board){return {version:1,board:board.id,stage:0,notes:['','','',''],complete:false,updated:new Date().toISOString()};}
export function validateCase(value,boards){if(!value||value.version!==1||!boards.some(b=>b.id===value.board)||!Number.isInteger(value.stage)||value.stage<0||value.stage>3||!Array.isArray(value.notes)||value.notes.length!==4||value.notes.some(n=>typeof n!=='string'||n.length>6000)||typeof value.complete!=='boolean')throw Error('Caso no válido.');return {version:1,board:value.board,stage:value.stage,notes:[...value.notes],complete:value.complete,updated:typeof value.updated==='string'?value.updated:new Date().toISOString()};}
export const narratedGuides=[
{id:'orientation',title:'Cómo empezar con una placa',text:'No intentes reconocer todas las piezas a la vez. Empieza por tres preguntas: qué entra, qué sale y cuál es la referencia. Busca los conectores. Después separa alimentación, control y salida. El color sirve para orientarte por funciones; no representa una tensión. Una red puede conectar varios bloques. Por eso distinguimos las redes propias de las compartidas. Al terminar, elige una conexión y explica qué evidencia del plano sostiene tu interpretación.'},
{id:'hypothesis',title:'De una sospecha a una comprobación',text:'Una hipótesis útil se puede comprobar. En lugar de escribir que la placa está mal, describe una condición concreta: la entrada existe, pero la salida esperada no aparece. Antes de medir, elige el punto, la referencia, la magnitud y el estado del circuito. Anota qué resultado esperas. Compara el resultado obtenido con esa predicción y decide qué explicación puedes descartar. En una placa virtual sin modelo eléctrico, estudia conexiones; no inventes medidas.'},
{id:'shared',title:'Por qué una red pertenece a varios bloques',text:'Los bloques funcionales ayudan a entender una placa, pero no son islas. Una alimentación o una masa suele conectar varias funciones. Si coloreamos toda esa red como si perteneciera a un solo bloque, la explicación puede resultar engañosa. Primero observa los componentes y conexiones propios del bloque. Después activa las redes compartidas. Las verás en blanco discontinuo. Así puedes estudiar cómo se relacionan las funciones sin confundir la clasificación con la conectividad.'}
];
